def render(locale, t):
    learned=''.join(f'<article><b>{i:02}</b><h3>{h}</h3><p>{p}</p></article>' for i,(h,p) in enumerate(t['learned'],1))
    choices=''.join(f'<button type="button" class="{"active" if i==0 else ""}" data-choice="c{i}">{x[0]}</button>' for i,x in enumerate(t['choices']))
    engine=''.join(f'<article><b>{i:02}</b><h3>{h}</h3><p>{p}</p></article>' for i,(h,p) in enumerate(t['steps'],1))
    products=''.join(f'<article><span>{i:02}</span><h3>{h}</h3><p>{p}</p></article>' for i,(h,p) in enumerate(t['products'],1))
    switch=''.join(f'<a href="/{l}/waltham-insight.html"'+(' aria-current="page"' if l==locale else '')+f'>{"DK" if l=="dk" else l.upper()}</a>' for l in ['dk','no','en','de'])
    content=','.join(f'c{i}:[{h!r},{p!r}]' for i,(_,h,p) in enumerate(t['choices']))
    return f'''<!doctype html><html lang="{t['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Waltham Insight — AI research, human verification and independent conclusions."><title>Waltham Insight — Waltham</title><link rel="stylesheet" href="../css/styles.css"><link rel="stylesheet" href="../css/waltham-insight.css"></head><body id="top"><header class="insight-nav"><div class="wrap"><a class="logo" href="index.html">Waltham<span>.</span><small>Insight</small></a><nav class="language-switcher">{switch}</nav><a class="back" href="index.html">← {t['back']}</a></div></header><main><section class="insight-hero"><div class="wrap"><p class="eyebrow">Waltham Insight</p><h1>{t['hero']}</h1><p class="hero-lead">{t['lead']}</p><div class="buttons"><a class="button primary" href="#question">{t['ask']}</a><a class="button ghost" href="#method">{t['method']}</a></div></div></section><section class="section wrap"><div class="insight-intro"><div><p class="label">{t['research']}</p><h2>{t['research_h']}</h2></div><div class="copy"><p>{t['research_p']}</p></div></div><p class="principle">{t['principle']}</p></section><figure class="insight-illustration wrap"><img src="../assets/waltham-insight-human-verification.png" alt="Waltham Insight human verification"><figcaption><span>{t['caption1']}</span><strong>{t['caption2']}</strong></figcaption></figure><section class="section wrap"><div class="roots-note"><p class="label">{t['judgement']}</p><div class="split"><h2>{t['judgement_h']}</h2><div class="copy"><p>{t['judgement_p']}</p></div></div></div></section><section class="section wrap"><p class="label">{t['experience']}</p><h2>{t['experience_h']}</h2><div class="learned-grid">{learned}</div></section><aside class="wrap development-note"><div><p class="label">{t['dev']}</p><h2>{t['dev_h']}</h2></div><div><p>{t['dev_p']}</p></div></aside><section class="section question-lab" id="question"><div class="wrap question-grid"><div><p class="label">{t['choose']}</p><h2>{t['choose_h']}</h2></div><div class="question-card"><div class="choice-grid">{choices}</div><div class="question-result" id="questionResult"><h3>{t['choices'][0][1]}</h3><p>{t['choices'][0][2]}</p></div></div></div></section><section class="section engine" id="method"><div class="wrap"><p class="label">Waltham Insight Engine</p><h2>{t['engine']}</h2><div class="engine-grid">{engine}</div></div></section><section class="section wrap"><p class="label">{t['universe']}</p><h2>{t['universe_h']}</h2><div class="products-grid">{products}</div></section><section class="section wrap"><div class="roots-note"><p class="label">{t['pr']}</p><div class="split"><h2>{t['pr_h']}</h2><div class="copy"><p>{t['pr_p']}</p></div></div></div></section><section class="section integrity"><div class="wrap integrity-grid"><div><p class="label">{t['integrity']}</p><p class="integrity-quote">{t['integrity_h']}</p></div><div class="evidence-box"><h3>Evidence</h3><div><span>Official statistics</span><strong>Documented</strong></div><div><span>Market data</span><strong>Supports</strong></div><div><span>Human verification</span><strong>Confirms</strong></div><div><span>Alternative explanations</span><strong>Tested</strong></div></div></div></section><section class="section wrap"><div class="roots-note"><p class="label">{t['roots']}</p><div class="split"><h2>{t['roots_h']}</h2><div class="copy"><p>{t['roots_p']}</p></div></div></div></section><section class="section insight-cta" id="contact"><div class="wrap contact-grid"><div><p class="label">{t['cta']}</p><h2>{t['cta_h']}</h2><p>{t['cta_p']}</p></div><div><a class="button primary" href="mailto:waltham@me.com?subject=Waltham%20Insight">{t['send']}</a></div></div></section></main><footer><div class="wrap"><a class="logo" href="index.html">Waltham<span>.</span></a><p>Insight Discovery · Human Verification · Market Pulse · Research-led PR.</p></div></footer><script>const content={{{content}}},result=document.getElementById('questionResult');document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('[data-choice]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const x=content[b.dataset.choice];result.innerHTML='<h3>'+x[0]+'</h3><p>'+x[1]+'</p>'}}));</script><script src="/js/cookie-notice.js"></script></body></html>'''

for locale,t in DATA.items():
    path = ROOT/locale/'waltham-insight.html'
    html = render(locale,t).replace('</head>','<link rel="stylesheet" href="../css/brand-logo.css"></head>',1)
    path.write_text(html,encoding='utf-8')
